test "t0" {
    assert (
        radboud_colon_concepts2labels(
            {
                "2": {
                    "concepts": {
                        "Diagnosis": [
                            ("0", "colon adenocarcinoma"),
                            ("1", "dysplasia"),
                            ("2", "moderate"),
                            ("3", "hyperplastic polyp"),
                            ("4", "10 mm")
                        ]
                    },
                    "slide_ids": ["1", "2"]
                }
            }
        )
        == {
            "2": {
                "labels": {"cancer": 1, "hgd": 0, "lgd": 1, "hyperplastic": 1, "ni": 0},
                "slide_ids": ["1", "2"]
            }
        }
    ) , "radboud_colon_concepts2labels() #2";;
}

